CREATE TYPE "KnowledgeSourceStatus" AS ENUM ('PENDING','APPROVED','REJECTED');
CREATE TYPE "KnowledgeReviewStatus" AS ENUM ('PENDING','APPROVED','REJECTED');
CREATE TYPE "KnowledgeImportStatus" AS ENUM ('DRAFT','VALIDATED','APPROVED','IMPORTED','ROLLED_BACK','FAILED');
CREATE TABLE "KnowledgeSource" ("id" TEXT PRIMARY KEY,"publisher" TEXT NOT NULL,"url" TEXT NOT NULL,"contentType" TEXT NOT NULL,"license" TEXT NOT NULL,"commercialUseAllowed" BOOLEAN NOT NULL,"attributionRequirements" TEXT,"modificationAllowed" BOOLEAN NOT NULL,"redistributionAllowed" BOOLEAN NOT NULL,"reviewDate" TIMESTAMP(3) NOT NULL,"status" "KnowledgeSourceStatus" NOT NULL DEFAULT 'PENDING',"reviewerNotes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "KnowledgeImportBatch" ("id" TEXT PRIMARY KEY,"version" TEXT NOT NULL UNIQUE,"status" "KnowledgeImportStatus" NOT NULL DEFAULT 'DRAFT',"report" JSONB,"approvedBy" TEXT,"approvedAt" TIMESTAMP(3),"importedAt" TIMESTAMP(3),"rolledBackAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "KnowledgeImportItem" ("id" TEXT PRIMARY KEY,"batchId" TEXT NOT NULL,"entityType" "KnowledgeEntityType" NOT NULL,"entityId" TEXT NOT NULL,"payload" JSONB NOT NULL,"status" "KnowledgeImportStatus" NOT NULL DEFAULT 'DRAFT',"diagnostic" TEXT, UNIQUE("batchId","entityId"));
CREATE TABLE "KnowledgeProvenance" ("id" TEXT PRIMARY KEY,"entityId" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"citation" TEXT NOT NULL,"reviewerStatus" "KnowledgeReviewStatus" NOT NULL DEFAULT 'PENDING',"scientificReview" "KnowledgeReviewStatus" NOT NULL DEFAULT 'PENDING',"version" TEXT NOT NULL,"importBatchId" TEXT NOT NULL, UNIQUE("entityId","sourceId","version"));
CREATE TABLE "KnowledgeImageRights" ("id" TEXT PRIMARY KEY,"entityId" TEXT NOT NULL,"imageSource" TEXT NOT NULL,"owner" TEXT NOT NULL,"license" TEXT NOT NULL,"attributionText" TEXT,"permittedUse" TEXT NOT NULL,"originalUrl" TEXT NOT NULL,"checksum" TEXT NOT NULL UNIQUE,"approvalStatus" "KnowledgeReviewStatus" NOT NULL DEFAULT 'PENDING',"reviewerNotes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "KnowledgeSource_status_idx" ON "KnowledgeSource"("status"); CREATE INDEX "KnowledgeImportBatch_status_idx" ON "KnowledgeImportBatch"("status"); CREATE INDEX "KnowledgeProvenance_importBatchId_idx" ON "KnowledgeProvenance"("importBatchId"); CREATE INDEX "KnowledgeImageRights_entityId_idx" ON "KnowledgeImageRights"("entityId"); CREATE INDEX "KnowledgeImageRights_approvalStatus_idx" ON "KnowledgeImageRights"("approvalStatus");
ALTER TABLE "KnowledgeImportItem" ADD FOREIGN KEY ("batchId") REFERENCES "KnowledgeImportBatch"("id") ON DELETE CASCADE; ALTER TABLE "KnowledgeProvenance" ADD FOREIGN KEY ("entityId") REFERENCES "KnowledgeEntity"("id") ON DELETE CASCADE; ALTER TABLE "KnowledgeProvenance" ADD FOREIGN KEY ("sourceId") REFERENCES "KnowledgeSource"("id") ON DELETE RESTRICT;
CREATE TABLE "KnowledgeFieldProvenance" ("id" TEXT PRIMARY KEY,"entityId" TEXT NOT NULL,"fieldPath" TEXT NOT NULL,"claimKey" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"citation" TEXT NOT NULL,"license" TEXT NOT NULL,"reviewerStatus" "KnowledgeReviewStatus" NOT NULL DEFAULT 'PENDING',"scientificReview" "KnowledgeReviewStatus" NOT NULL DEFAULT 'PENDING',"languageReview" "KnowledgeReviewStatus" NOT NULL DEFAULT 'PENDING',"geographicScope" TEXT,"importBatchId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("entityId","fieldPath","sourceId","importBatchId")); CREATE INDEX "KnowledgeFieldProvenance_importBatchId_idx" ON "KnowledgeFieldProvenance"("importBatchId");
